from decimal import Decimal, InvalidOperation, localcontext
from datetime import date

_CENT = Decimal('0.01')

def _quantize_2(value):
    if value == 0:
        return Decimal('0.00')
    with localcontext() as ctx:
        parts = value.as_tuple()
        ctx.prec = max(28, len(parts.digits) + abs(parts.exponent) + 10)
        return value.quantize(_CENT)

def _parse_money(value):
    if not isinstance(value, str):
        raise ValueError('value must be a string')
    try:
        parsed = Decimal(value)
    except (InvalidOperation, ValueError, ArithmeticError):
        raise ValueError('invalid decimal value') from None
    if not parsed.is_finite():
        raise ValueError('invalid decimal value')
    parts = parsed.as_tuple()
    if parts.exponent < -2:
        extra = -parts.exponent - 2
        digits = parts.digits
        if any(d != 0 for d in digits):
            if extra >= len(digits) or any(d != 0 for d in digits[-extra:]):
                raise ValueError('too many decimal places')
    return _quantize_2(parsed)

def _validate_date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    if len(value) != 10 or value[4] != '-' or value[7] != '-':
        raise ValueError('invalid date')
    if not all('0' <= c <= '9' for c in value[0:4] + value[5:7] + value[8:10]):
        raise ValueError('invalid date')
    try:
        date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        raise ValueError('invalid date') from None

def _prepare(transactions, opening_balance):
    opening = _parse_money(opening_balance)
    if not isinstance(transactions, list):
        raise ValueError('transactions must be a list')
    seen = set()
    rows = []
    for item in transactions:
        if not isinstance(item, dict):
            raise ValueError('transaction must be a dict')
        if 'id' not in item or 'value_date' not in item or 'booking_date' not in item or 'amount' not in item:
            raise ValueError('missing transaction key')
        tx_id = item['id']
        if not isinstance(tx_id, str) or tx_id == '':
            raise ValueError('invalid id')
        if tx_id in seen:
            raise ValueError('duplicate id')
        seen.add(tx_id)
        _validate_date(item['value_date'])
        _validate_date(item['booking_date'])
        amount = _parse_money(item['amount'])
        rows.append({'id': tx_id, 'value_date': item['value_date'], 'booking_date': item['booking_date'], 'amount': amount})
    rows.sort(key=lambda r: (r['value_date'], r['booking_date'], r['id']))
    return opening, rows

def running_balance(transactions, opening_balance):
    opening, rows = _prepare(transactions, opening_balance)
    result = []
    balance = opening
    with localcontext() as ctx:
        ctx.prec = 100
        for row in rows:
            balance = balance + row['amount']
            if balance == 0:
                balance = Decimal('0.00')
            else:
                balance = balance.quantize(_CENT)
            result.append({'id': row['id'], 'value_date': row['value_date'], 'booking_date': row['booking_date'], 'amount': row['amount'], 'balance': balance})
    return result

def closing_balance(transactions, opening_balance):
    rows = running_balance(transactions, opening_balance)
    if rows:
        return rows[-1]['balance']
    return _parse_money(opening_balance)

