import csv
from datetime import date
from decimal import Decimal, localcontext

_CENT = Decimal('0.01')

def _quantize_2(value):
    if value == 0:
        return Decimal('0.00')
    with localcontext() as ctx:
        parts = value.as_tuple()
        ctx.prec = max(28, len(parts.digits) + abs(parts.exponent) + 10)
        return value.quantize(_CENT)

def _is_digits(text):
    return text != '' and all('0' <= c <= '9' for c in text)

def _parse_spanish_amount(raw):
    if raw == '':
        raise ValueError('invalid amount')
    negative = False
    body = raw
    if body.startswith('-'):
        negative = True
        body = body[1:]
    if body == '' or body.count(',') != 1:
        raise ValueError('invalid amount')
    int_part, dec_part = body.split(',')
    if len(dec_part) not in (1, 2) or not _is_digits(dec_part):
        raise ValueError('invalid amount')
    if int_part == '':
        raise ValueError('invalid amount')
    if '.' in int_part:
        groups = int_part.split('.')
        if len(groups[0]) < 1 or len(groups[0]) > 3 or not _is_digits(groups[0]):
            raise ValueError('invalid amount')
        for group in groups[1:]:
            if len(group) != 3 or not _is_digits(group):
                raise ValueError('invalid amount')
        digits_only = ''.join(groups)
    else:
        if not _is_digits(int_part):
            raise ValueError('invalid amount')
        digits_only = int_part
    normalized = ('-' if negative else '') + digits_only + '.' + dec_part
    return _quantize_2(Decimal(normalized))

def _parse_date_field(raw, line_no):
    if len(raw) != 10 or raw[2] != '/' or raw[5] != '/':
        raise ValueError(f'line {line_no}: invalid date')
    if not all('0' <= c <= '9' for c in raw[0:2] + raw[3:5] + raw[6:10]):
        raise ValueError(f'line {line_no}: invalid date')
    try:
        parsed = date(int(raw[6:10]), int(raw[3:5]), int(raw[0:2]))
    except ValueError:
        raise ValueError(f'line {line_no}: invalid date') from None
    return parsed.isoformat()

def parse_bank_csv(text):
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    if text.startswith(chr(65279)):
        text = text[1:]
    lines = text.splitlines()
    header_seen = False
    result = []
    for line_no, line in enumerate(lines, start=1):
        if line.strip() == '':
            continue
        if not header_seen:
            if line != 'Fecha;Concepto;Importe;Saldo':
                raise ValueError('invalid header')
            header_seen = True
            continue
        try:
            parsed_rows = list(csv.reader([line], delimiter=';', quotechar='"', doublequote=True, strict=True))
        except csv.Error:
            raise ValueError(f'line {line_no}: invalid CSV') from None
        if len(parsed_rows) != 1 or len(parsed_rows[0]) != 4:
            raise ValueError(f'line {line_no}: expected 4 fields')
        row = parsed_rows[0]
        iso_date = _parse_date_field(row[0].strip(), line_no)
        amount_text = row[2].strip()
        if amount_text == '':
            raise ValueError(f'line {line_no}: invalid amount')
        try:
            amount = _parse_spanish_amount(amount_text)
        except ValueError:
            raise ValueError(f'line {line_no}: invalid amount') from None
        balance_text = row[3].strip()
        if balance_text == '':
            balance = None
        else:
            try:
                balance = _parse_spanish_amount(balance_text)
            except ValueError:
                raise ValueError(f'line {line_no}: invalid amount') from None
        result.append({'date': iso_date, 'concept': row[1], 'amount': amount, 'balance': balance})
    if not header_seen:
        raise ValueError('missing header')
    return result

def summarize_transactions(transactions):
    if not isinstance(transactions, list):
        raise ValueError('transactions must be a list')
    credits = Decimal('0.00')
    debits = Decimal('0.00')
    for item in transactions:
        if not isinstance(item, dict):
            raise ValueError('transaction must be a dict')
        if 'amount' not in item or 'date' not in item:
            raise ValueError('missing transaction key')
        amount = item['amount']
        if not isinstance(amount, Decimal) or not amount.is_finite():
            raise ValueError('invalid amount')
        if not isinstance(item['date'], str):
            raise ValueError('invalid date')
        if amount > 0:
            credits = credits + amount
        elif amount < 0:
            debits = debits + amount
    credits_q = _quantize_2(credits)
    debits_q = _quantize_2(debits)
    net_q = _quantize_2(credits_q + debits_q)
    first_date = transactions[0]['date'] if transactions else None
    last_date = transactions[-1]['date'] if transactions else None
    return {'count': len(transactions), 'credits': credits_q, 'debits': debits_q, 'net': net_q, 'first_date': first_date, 'last_date': last_date}

