_TABLE = 'TRWAGMYFPDXBNJZSQVHLCKE'
_CIF_INITIALS = set('ABCDEFGHJKLMPQRSUVW')
_CIF_DIGIT_REQUIRED = set('ABEH')
_CIF_LETTER_REQUIRED = set('KPQRSW')
_CIF_CONTROL_LETTERS = 'JABCDEFGHI'

def _is_digit(ch):
    return '0' <= ch <= '9'

def _is_letter(ch):
    return 'A' <= ch <= 'Z'

def classify_spanish_id(text):
    if not isinstance(text, str):
        return None
    normalized = text.replace(' ', '').replace('-', '').upper()
    if len(normalized) != 9:
        return None
    first = normalized[0]
    if _is_digit(first):
        if not all(_is_digit(c) for c in normalized[0:8]):
            return None
        if not _is_letter(normalized[8]):
            return None
        expected = _TABLE[int(normalized[0:8]) % 23]
        return 'NIF' if normalized[8] == expected else None
    if first in 'XYZ':
        if not all(_is_digit(c) for c in normalized[1:8]):
            return None
        if not _is_letter(normalized[8]):
            return None
        prefix = {'X': '0', 'Y': '1', 'Z': '2'}[first]
        expected = _TABLE[int(prefix + normalized[1:8]) % 23]
        return 'NIE' if normalized[8] == expected else None
    if first not in _CIF_INITIALS:
        return None
    if not all(_is_digit(c) for c in normalized[1:8]):
        return None
    control = normalized[8]
    if not (_is_digit(control) or _is_letter(control)):
        return None
    total = 0
    digits = [int(c) for c in normalized[1:8]]
    for index, digit in enumerate(digits):
        if index % 2 == 0:
            doubled = digit * 2
            total += doubled // 10 + doubled % 10
        else:
            total += digit
    control_digit = (10 - (total % 10)) % 10
    control_letter = _CIF_CONTROL_LETTERS[control_digit]
    if first in _CIF_DIGIT_REQUIRED:
        return 'CIF' if control == str(control_digit) else None
    if first in _CIF_LETTER_REQUIRED:
        return 'CIF' if control == control_letter else None
    return 'CIF' if control == str(control_digit) or control == control_letter else None

def is_valid_spanish_id(text):
    return classify_spanish_id(text) is not None
